def text(x,y,t,size=23,color=N):return f'<text x="{x}" y="{y}" font-family="Noto Sans CJK JP" font-size="{size}" fill="{color}">{html.escape(t)}</text>'
def line(x1,y1,x2,y2,c=N,w=4,dash=''):return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="{w}" stroke-dasharray="{dash}"/>'
def rect(x,y,w,h,c='none',stroke=N,sw=4):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5" fill="{c}" stroke="{stroke}" stroke-width="{sw}"/>'
def circle(x,y,r,c='none',stroke=N):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}" stroke="{stroke}" stroke-width="4"/>'
def path(d,c='none',stroke=N,w=4):return f'<path d="{d}" fill="{c}" stroke="{stroke}" stroke-width="{w}"/>'
def arrow(x1,y1,x2,y2,c=N):return line(x1,y1,x2,y2,c)+f'<path d="M{x2-10} {y2-7} L{x2} {y2} L{x2-10} {y2+7}" fill="none" stroke="{c}" stroke-width="4" transform="rotate({__import__("math").degrees(__import__("math").atan2(y2-y1,x2-x1))} {x2} {y2})"/>'
def axes():return line(110,410,110,150)+line(110,410,850,410)
def person(x,y):return circle(x,y,24,'#e8c8a2')+path(f'M{x-35} {y+130} L{x-25} {y+45} Q{x} {y+25} {x+25} {y+45} L{x+35} {y+130}', '#d8e3eb')
def gear(x,y):return circle(x,y,55,'#ccd6d9')+circle(x,y,22,B)+''.join(line(x+__import__('math').cos(a)*55,y+__import__('math').sin(a)*55,x+__import__('math').cos(a)*72,y+__import__('math').sin(a)*72,N,12) for a in [i*__import__('math').pi/4 for i in range(8)])
